import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    return new Job(this, interval);
  }

  addJob(job) {
    this.jobs.push(job);
    return job;
  }

  getJobs(tag) {
    if (tag === undefined) {
      return this.jobs.slice();
    }

    return this.jobs.filter((job) => job.hasTag(tag));
  }

  clear(tag) {
    if (tag === undefined) {
      this.jobs = [];
      return;
    }

    this.jobs = this.jobs.filter((job) => !job.hasTag(tag));
  }
}

